    'iterable' that satisfy 'pred' and [falses] is all the rest."""
def partition(pred: Any, iterable: Any) -> object {
    trues = [];
    falses = [];
    for item in iterable {
        if pred(item) {
            trues.append(item);
        } else {
            falses.append(item);
        }
    }
    return (trues, falses);
}

